function st30Text(g,x,y,t,col,sh){const F=typeof PXFONT!=='undefined'?PXFONT:{};for(const ch of t){const f=F[ch]||F[' ']||'';
    for(let j=0;j<5;j++)for(let i=0;i<3;i++)if(f[j*3+i]==='1'){if(sh){g.fillStyle=sh;g.fillRect(x+i+1,y+j+1,1,1);}g.fillStyle=col;g.fillRect(x+i,y+j,1,1);}x+=4;}}
function st30Board(g,cx,y,text,style){const t=String(text||'').toUpperCase().replace(/[^A-Z0-9 &.]/g,'').replace(/\s+/g,' ').trim().slice(0,22);if(!t)return;
  const C=ST30_BOARD[style]||ST30_BOARD.plank,painted=style!=='plank';const h=painted?12:10,w=t.length*4+(painted?13:9),x0=Math.round(cx-w/2),y0=painted?y-2:y;
  const R=(x,y,w,h,c)=>{g.fillStyle=c;g.fillRect(x,y,w,h);};
  if(painted){R(x0+6,y0-4,2,4,'#383a4a');R(x0+w-8,y0-4,2,4,'#383a4a');}   // the brackets it hangs from
  R(x0,y0,w+1,h+1,C.face);R(x0,y0,w+1,1,C.top);R(x0,y0+1,w+1,1,C.mid);R(x0,y0+h,w+1,1,C.bot);
  R(x0-1,y0,1,h+1,'#1d1018');R(x0+w+1,y0,1,h+1,'#1d1018');R(x0,y0-1,w+1,1,'#1d1018');R(x0,y0+h+1,w+1,1,'#1d1018');
  if(painted){g.fillStyle=C.rim;for(let x=x0+2;x<=x0+w-2;x++){g.fillRect(x,y0+2,1,1);g.fillRect(x,y0+h-2,1,1);}for(let yy=y0+2;yy<=y0+h-2;yy++){g.fillRect(x0+2,yy,1,1);g.fillRect(x0+w-2,yy,1,1);}}
  else{R(x0+2,y0+5,1,1,'#383a4a');R(x0+w-2,y0+5,1,1,'#383a4a');R(x0+Math.round(w*.4),y0+h-2,5,1,C.mid);}   // nails; a split in the plank
  st30Text(g,x0+(painted?7:5),y0+(painted?4:3),t,C.ink,C.sh);}
